const Socials=[{url:"https://www.facebook.com/ichimaki.cos",label:"Facebook",image:"images/fb.png",selector:"facebook"},{url:"https://www.tiktok.com/@ichimaki.cos",label:"TikTok",image:"images/tiktok.png",selector:"tiktok"},{url:"https://www.instagram.com/ichimaki.cos",label:"Instagram",image:"images/ig.png",selector:"instagram"},{url:"https://www.github.com/IchimakiKasura",label:"Github",image:"https://skillicons.dev/icons?i=github",selector:"github"},{url:"https://www.youtube.com/@KasuraIchimaki",label:"Youtube",image:"images/youtube.png",selector:"youtube"},{url:"https://discord.com/users/716593062217908274",label:"Discord",image:"https://skillicons.dev/icons?i=discord",selector:"discord"},{url:"https://ichimakikasura.github.io",label:"Portfolio",image:"https://avatars.githubusercontent.com/u/80595346?v=4%253F",selector:"portfolio",borderRadius:"50%"}];(()=>{const t=document.querySelector(".social-buttons");Socials.forEach(e=>{const a=document.createElement("a");a.href=e.url,a.target="_blank",a.className="social-btn",a.title=e.label,a.dataset.platform=e.selector;const i=document.createElement("img");i.src=e.image,i.alt=e.label,i.loading="lazy",e.borderRadius&&(i.style.borderRadius=e.borderRadius),a.appendChild(i),t.appendChild(a)})})();